package net.officefloor.hq.app.rollup;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import java.util.TreeSet;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.setting.SheetParentLink;
import net.officefloor.hq.app.setting.SheetParentRepository;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * The people of a sheet's tree (its top sheet, found up its parents, and all the top sheet's
 * descendants) whose name or an alias contains a text, case ignored: the sheet's own people first in
 * list order, then the other sheets' by sheet id, each shown as {@code <name> (<grade>)} with the grade
 * in force on their sheet's today, and with their due-total as their sheet shows it.
 */
@Service
public class TreeSearchService {

    /** A person found: their sheet, name with their grade in force on that sheet's today, and due-total with two decimals, or "n/a". */
    public record Found(String sheetId, String name, String dueTotal) {
    }

    private final SheetParentRepository parents;
    private final PersonRepository people;
    private final Rollup rollup;
    private final SheetService sheets;

    public TreeSearchService(SheetParentRepository parents, PersonRepository people, Rollup rollup,
            SheetService sheets) {
        this.parents = parents;
        this.people = people;
        this.rollup = rollup;
        this.sheets = sheets;
    }

    @Transactional(readOnly = true)
    public List<Found> search(String sheetId, String text) {
        String needle = text == null ? "" : text.toLowerCase(Locale.ROOT);
        List<Found> found = new ArrayList<>(searchSheet(sheetId, needle));
        for (String other : treeOf(sheetId)) {
            if (!other.equals(sheetId)) found.addAll(searchSheet(other, needle));
        }
        return found;
    }

    private List<Found> searchSheet(String sheetId, String needle) {
        Rollup.Snapshot figures = rollup.snapshot(sheetId);
        List<Found> found = new ArrayList<>();
        LocalDate today = null;
        for (Person person : people.findInListOrder(sheetId)) {
            if (!matches(person, needle)) continue;
            Rollup.Figures theirs = figures.people().get(person.getId());
            BigDecimal due = theirs == null ? null : theirs.dueTotal();
            if (today == null) today = sheets.today(sheetId);
            found.add(new Found(sheetId, person.getName() + " (" + person.gradeOn(today) + ")",
                    due == null ? "n/a" : due.setScale(2, RoundingMode.HALF_EVEN).toPlainString()));
        }
        return found;
    }

    private static boolean matches(Person person, String needle) {
        if (person.getName().toLowerCase(Locale.ROOT).contains(needle)) return true;
        return person.getAliases().stream().anyMatch(alias -> alias.toLowerCase(Locale.ROOT).contains(needle));
    }

    /** The sheets of the sheet's tree, by id. */
    private Set<String> treeOf(String sheetId) {
        String top = sheetId;
        Set<String> up = new HashSet<>(List.of(sheetId));
        for (String parent = parentOf(top); parent != null && up.add(parent); parent = parentOf(parent)) {
            top = parent;
        }
        Set<String> tree = new TreeSet<>(List.of(top));
        Deque<String> next = new ArrayDeque<>(List.of(top));
        while (!next.isEmpty()) {
            for (SheetParentLink child : parents.findByParentId(next.pop())) {
                if (tree.add(child.getSheetId())) next.add(child.getSheetId());
            }
        }
        return tree;
    }

    private String parentOf(String id) {
        return parents.findById(id).map(SheetParentLink::getParentId).orElse(null);
    }
}
package net.officefloor.hq.app.rollup;

import jakarta.servlet.http.HttpServletRequest;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Size;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.asof.AsOf;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api/sheets")
@Validated
public class ConsolidatedController {

    private final ConsolidatedService service;
    private final TreeSearchService search;

    public ConsolidatedController(ConsolidatedService service, TreeSearchService search) {
        this.service = service;
        this.search = search;
    }

    /** The figures of the sheet's descendants added up; the screen adds its own to consolidate them. Read
     *  from a screen set to an as-of date, every sheet of the tree as it stood at the end of that day. */
    @GetMapping("/{id}/descendants")
    public ConsolidatedService.Descendants descendants(@PathVariable @NotBlank @Size(max = 100) String id,
            HttpServletRequest request) {
        return service.descendantsOf(id.trim(), AsOf.of(request).orElse(null));
    }

    /** Per grade, the sheet's summary due-total; empty for a sheet that does not exist. Read as the store
     *  holds it now. */
    @GetMapping("/{id}/grade-due-totals")
    public Map<String, String> gradeDueTotals(@PathVariable @NotBlank @Size(max = 100) String id) {
        return service.gradeDueTotalsOf(id.trim());
    }

    /** The people over the sheet's tree whose name or an alias contains the text, case ignored. */
    @GetMapping("/{id}/tree-search")
    public List<TreeSearchService.Found> treeSearch(@PathVariable @NotBlank @Size(max = 100) String id,
            @RequestParam(defaultValue = "") @Size(max = 200) String text) {
        return search.search(id.trim(), text);
    }
}
import { HttpClient, HttpContext } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { LIVE_READ } from '../../core/as-of.interceptor';

/** A sheet's descendants (its children, then theirs, and so on) and their figures added up. */
export interface DescendantsView {
  sheets: string[];
  peopleCount: number;
  /** Each descendant's due-total as that sheet shows it, added up, with two decimals. */
  dueTotal: string;
  /** Each descendant's overdue-total as that sheet shows it, added up, with two decimals. */
  overdueTotal: string;
  /** The sheet's own figures as it shows them now. */
  ownPeopleCount: number;
  ownDueTotal: string;
  ownOverdueTotal: string;
  /** Per grade, the due-totals of the descendants' people on it today who are not retired, added up, with
   *  two decimals. */
  gradeDueTotals: Record<string, string>;
  /** Per status, how many of the descendants' claims have it. */
  statusCounts: Record<string, number>;
  /** Each of the descendants' people: their name and aliases as names are compared, and their figures. */
  people: TreePersonFigures[];
}

/** A person's figures on a sheet of the tree: their name and aliases as names are compared (trimmed, lower-cased),
 *  their due-total with two decimals (null for n/a) and their overdue-total with two decimals. */
export interface TreePersonFigures {
  keys: string[];
  dueTotal: string | null;
  overdueTotal: string;
}

// The figures of a sheet's descendants, and its own: while the screen shows the sheet as of a date, every
// sheet of the tree as it stood at the end of that day.
@Injectable({ providedIn: 'root' })
export class ConsolidatedApi {
  private readonly http = inject(HttpClient);

  descendants(sheetId: string): Promise<DescendantsView> {
    return firstValueFrom(this.http.get<DescendantsView>(`/api/sheets/${encodeURIComponent(sheetId)}/descendants`));
  }
}

/** A person found over a sheet's tree: their sheet, name and due-total (two decimals, or n/a). */
export interface TreeSearchHit {
  sheetId: string;
  name: string;
  dueTotal: string;
}

// The people over a sheet's tree whose name or an alias contains the text, case ignored: the sheet's
// own first in list order, then the other sheets' by sheet id. Read live, as the store holds them now.
@Injectable({ providedIn: 'root' })
export class TreeSearchApi {
  private readonly http = inject(HttpClient);

  search(sheetId: string, text: string): Promise<TreeSearchHit[]> {
    return firstValueFrom(this.http.get<TreeSearchHit[]>(`/api/sheets/${encodeURIComponent(sheetId)}/tree-search`,
      { params: { text }, context: new HttpContext().set(LIVE_READ, true) }));
  }
}

// Per grade, a sheet's summary due-total with two decimals; none for a sheet that does not exist. Read
// live, as the store holds it now.
@Injectable({ providedIn: 'root' })
export class CompareSheetApi {
  private readonly http = inject(HttpClient);

  gradeDueTotals(sheetId: string): Promise<Record<string, string>> {
    return firstValueFrom(this.http.get<Record<string, string>>(`/api/sheets/${encodeURIComponent(sheetId)}/grade-due-totals`,
      { context: new HttpContext().set(LIVE_READ, true) }));
  }
}

